                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
  CREATE OR REPLACE FORCE EDITIONABLE VIEW "TENANT_EVENT_REVIEW_V" ("EVENT_ID", "EVENT_SERIAL_NO", "TENANT_ID", "AUDIT_NAME", "CREATION_DATE", "END_TIME", "MAIN_ORG_ID", "MAP_ID", "BASE_ID", "BASE_NAME", "FAB_ID", "FAB_NAME", "MAP_AREA_Y_ID", "MAP_AREA_Y_NAME", "MAP_AREA_X_ID", "MAP_AREA_X_NAME", "FIRST_EVENT_CODE", "FIRST_EVENT_CATEGORY_NAME", "SECOND_EVENT_CODE", "SECOND_EVENT_CATEGORY_NAME", "PHENOMENON_CODE", "EVENT_PHENOMENON_NAME", "DESCRIPTION", "IMAGES_URL", "IS_STOP_LINE", "IS_KEY_PROCESS", "SUBMIT_SOURCE", "CALL_RANGE", "BEGIN_TIME", "IS_CREATE_GROUP_CHAT", "GROUP_CHAT_ID", "GROUP_CHAT_QRCODE_URL", "CALL_RANGE_NAME", "SUBMIT_USER_ID", "SUBMIT_NAME", "SUBMIT_AVATAR", "EXT_USER_ID", "EXT_USER_NAME", "EXT_ORG_ID", "MAIN_ORG_NAME", "MAIN_NAME", "AUDIT_STATE", "ABNORMAL_ANALYSIS_USER", "BASE_DEPT_ID") AS     
  SELECT EVENT.EVENT_ID,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
       EVENT.EVENT_SERIAL_NO,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
       EVENT.TENANT_ID,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
       REVIEW.AUDIT_NAME,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
       EVENT.BEGIN_TIME                                                        AS CREATION_DATE,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
       EVENT.END_TIME,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
       EVENT.MAIN_ORG_ID,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
       MAP.MAP_ID,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
       MAP.BASE_ID,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
       MAP.BASE_NAME,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
       map.FAB_ID,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
       map.FAB_NAME,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
       map.MAP_AREA_Y_ID,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
       map.MAP_AREA_Y_NAME,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
       map.MAP_AREA_X_ID,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
       map.MAP_AREA_X_NAME,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
       EVENT.FIRST_EVENT_CODE,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
       LIBRARY.FIRST_EVENT_CATEGORY_NAME,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
       EVENT.SECOND_EVENT_CODE,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
       LIBRARY.SECOND_EVENT_CATEGORY_NAME,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
       EVENT.PHENOMENON_CODE,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
       LIBRARY.EVENT_PHENOMENON_NAME,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
       EVENT.DESCRIPTION,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
       EVENT.IMAGES_URL,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
       EVENT.IS_STOP_LINE,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
       EVENT.IS_KEY_PROCESS,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
       EVENT.SUBMIT_SOURCE,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
       EVENT.CALL_RANGE,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
       EVENT.BEGIN_TIME,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
       EVENT.IS_CREATE_GROUP_CHAT,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
       EVENT.GROUP_CHAT_ID,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
       EVENT.GROUP_CHAT_QRCODE_URL,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
       (SELECT listagg(NAME, ',')                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
        FROM MPF_SHARE_DEPT_V                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
        WHERE EXT_ORG_ID IN (SELECT * FROM TABLE (SPLITSTR(CALL_RANGE, ',')))) AS CALL_RANGE_NAME,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
       EVENT.SUBMIT_USER_ID,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
       NVL(BASIC1.NAME, EVENT.SUBMIT_SOURCE)                                   AS SUBMIT_NAME,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
       BASIC1.AVATAR                                                           AS SUBMIT_AVATAR,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
       BASIC2.EXT_USER_ID,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
       BASIC2.NAME                                                             AS EXT_USER_NAME,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
       BASIC2.EXT_ORG_ID,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
       (SELECT_DEPT_NAME(EVENT.MAIN_ORG_ID))                                   AS MAIN_ORG_NAME,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
--        (SELECT_DEPT_NAME(EVENT.MAIN_ORG_ID)) || '/' ||                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
--        select_dept_manager(map.FAB_ID, EVENT.MAIN_ORG_ID, EVENT.TENANT_ID)     AS MAIN_NAME,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
       (SELECT_DEPT_NAME(EVENT.MAIN_ORG_ID))                                   AS MAIN_NAME,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
       NVL(REVIEW.AUDIT_STATE, 'WAIT')                                         AS AUDIT_STATE,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
       REVIEW.ABNORMAL_ANALYSIS_USER,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
       event.BASE_DEPT_ID                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
FROM TENANT_EVENT EVENT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
         INNER JOIN TENANT_EVENT_FOLLOW_USERS FOLLOW                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                    ON EVENT.EVENT_ID = FOLLOW.EVENT_ID                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                        AND FOLLOW.IS_FINAL_HANDLER = 1 and FOLLOW.BASE_DEPT_ID=EVENT.BASE_DEPT_ID                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
         LEFT JOIN MPF_USER_BASIC_V BASIC1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                   ON EVENT.SUBMIT_USER_ID = BASIC1.EXT_USER_ID and BASIC1.BASE_DEPT_ID=EVENT.BASE_DEPT_ID                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
         LEFT JOIN MPF_USER_BASIC_V BASIC2                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                   ON FOLLOW.EXT_USER_ID = BASIC2.EXT_USER_ID and BASIC2.BASE_DEPT_ID=FOLLOW.BASE_DEPT_ID                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
         LEFT JOIN FND_MAPS_AREAS_ASSO_V MAP                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                   ON EVENT.MAP_ID = MAP.MAP_ID and map.BASE_DEPT_ID=event.BASE_DEPT_ID                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
         LEFT JOIN TENANT_EVENT_LIBRARY_V LIBRARY                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
                   ON EVENT.FIRST_EVENT_CODE = LIBRARY.FIRST_EVENT_CATEGORY_CODE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                       AND EVENT.SECOND_EVENT_CODE = LIBRARY.SECOND_EVENT_CATEGORY_CODE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                       AND EVENT.PHENOMENON_CODE = LIBRARY.EVENT_PHENOMENON_CODE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                       AND EVENT.TENANT_ID = LIBRARY.TENANT_ID and LIBRARY.BASE_DEPT_ID=event.BASE_DEPT_ID                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
         LEFT JOIN TENANT_EVENT_REVIEW REVIEW                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                   ON REVIEW.EVENT_ID = EVENT.EVENT_ID and REVIEW.BASE_DEPT_ID=event.BASE_DEPT_ID                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
WHERE EVENT.DEL_FLAG = 0                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
  AND EVENT.STATUS = 'RESOLVED';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    

